// ===== CONFIGURACIÓN (queda privada en n8n) ==================================
const WATCHLIST = ['Microsoft', 'Cisco', 'Fortinet', 'Citrix', 'Apple', 'Linux', 'VMware', 'Oracle'];
const DASHBOARD = 'https://cjlasnibat.github.io/vuln-pulse/';
const MODEL = 'claude-sonnet-4-5';   // revisa el nombre vigente en docs.claude.com → Models
const RECIPIENTS = {
  oficial: 'oficial@tudominio.cl',
  gerente: 'gerente.ti@tudominio.cl',
  ciso:    'ciso@tudominio.cl',
};
// ============================================================================

const r = $('Reporte semanal').first().json;
const prevRaw = $input.first().json;                       // snapshot de hace 7 días (puede no existir)
const prev = prevRaw && prevRaw.cve_7d ? prevRaw : null;
const s = r.summary;
const terms = WATCHLIST.map(t => t.toLowerCase());
const mine = (v, p) => terms.some(t => `${v || ''} ${p || ''}`.toLowerCase().includes(t));
const pick = (o, keys) => Object.fromEntries(keys.map(k => [k, o[k]]));
const delta = (cur, old) => (old == null ? null : cur - old);

const kev = (r.kev_new || []).map(k => ({
  cve: k.cveID, fabricante: k.vendorProject, producto: k.product, vulnerabilidad: k.vulnerabilityName,
  agregada: k.dateAdded, plazo_cisa: k.dueDate, ransomware: k.knownRansomwareCampaignUse,
  epss: k.epss ? +(k.epss.epss * 100).toFixed(2) : null, en_mis_tecnologias: mine(k.vendorProject, k.product),
}));
const slimCve = c => ({
  cve: c.cve_id, fabricante: c.vendor, producto: c.product, cvss: c.cvss && c.cvss.score,
  cwe: (c.cwe || [])[0] || null, ssvc_explotacion: c.ssvc && c.ssvc.exploitation,
  automatizable_impacto_total: !!(c.ssvc && c.ssvc.automatable === 'yes' && c.ssvc.technical_impact === 'total'),
  epss_pct: c.epss ? +(c.epss.epss * 100).toFixed(2) : null, en_mis_tecnologias: mine(c.vendor, c.product),
});
const crit = (r.critical_cves || []).map(slimCve);
const exploited = (r.ssvc_poc_or_active || []).map(slimCve);

const common = {
  ventana: r.window, generado: r.generated_at, tablero: DASHBOARD,
  fuentes_ok: Object.fromEntries(Object.entries(r.sources_status).map(([k, v]) => [k, v.ok])),
  mis_tecnologias: WATCHLIST,
  kev: { agregadas: s.kev_added, total_catalogo: s.kev_catalog_total, con_ransomware: s.kev_ransomware_known,
         variacion_vs_semana_previa: delta(s.kev_added, prev && prev.kev.added_7d), detalle: kev },
  cve: { nuevos: s.cve_new, por_severidad: s.cve_by_severity,
         variacion_nuevos_vs_semana_previa: delta(s.cve_new, prev && prev.cve_7d.new),
         variacion_criticos_vs_semana_previa: delta(s.cve_by_severity.CRITICAL || 0, prev && (prev.cve_7d.by_severity || {}).CRITICAL),
         ssvc_poc_o_activa: s.ssvc_poc_or_active, automatizables_impacto_total: s.ssvc_automatable_total_impact,
         epss_ge_10pct: s.epss_ge_10pct },
};

const facts = {
  oficial: { ...common,
    criticos_en_mis_tecnologias: crit.filter(c => c.en_mis_tecnologias).slice(0, 15),
    con_explotacion_ssvc: [...new Map(exploited.filter(c => c.ssvc_explotacion === 'active').slice(0, 10)
      .concat(exploited.filter(c => c.en_mis_tecnologias).slice(0, 15)).map(c => [c.cve, c])).values()],
    criticos_globales_top: crit.slice(0, 10) },
  gerente: { ...common,
    top_fabricantes: s.top_vendors.slice(0, 10), top_cwe: s.top_cwe.slice(0, 8),
    criticos_en_mis_tecnologias: crit.filter(c => c.en_mis_tecnologias).length,
    pct_sin_cvss: +(100 - s.cve_with_cvss_pct).toFixed(1) },
  ciso: { ...common,
    fabricantes_kev_semana: s.kev_vendors, top_cwe: s.top_cwe.slice(0, 5),
    metricas_internas_pendientes: ['Exposición KEV propia', 'Ventana de exposición KEV', 'Excepciones de riesgo', 'Riesgo de terceros'] },
};

const ROLE = {
  oficial: { nombre: 'Oficial de seguridad', foco: 'qué atender hoy y esta semana: KEV en sus tecnologías, plazos de CISA vencidos o próximos, CVE con explotación activa o PoC. Termina con una lista de acciones concretas priorizadas (P0/P1).', largo: '250-350 palabras' },
  gerente: { nombre: 'Gerente de TI', foco: 'carga de trabajo de parcheo: volumen y su variación, fabricantes que concentran esfuerzo, críticos en sus tecnologías y qué planificar en las ventanas de mantención. Lenguaje operativo, sin jerga innecesaria.', largo: '200-300 palabras' },
  ciso:    { nombre: 'CISO', foco: 'riesgo y tendencia: ritmo de explotación confirmada, peso del perímetro, si algo exige escalar a la gerencia, y qué métricas internas faltan para medir la exposición propia. Tono ejecutivo.', largo: '150-250 palabras' },
};

const SYSTEM = [
  'Eres analista de inteligencia de vulnerabilidades. Redactas en español de Chile, claro y directo.',
  'Reglas estrictas:',
  '1. Usa SOLO los datos del JSON entregado. No calcules cifras nuevas ni inventes CVE, productos, fechas o porcentajes.',
  '2. Cada afirmación sobre una vulnerabilidad lleva su CVE.',
  '3. Si una fuente aparece con fuentes_ok=false, dilo en una línea y no uses esos datos.',
  '4. Si una variación es null, no hay semana previa para comparar: dilo así, sin estimar.',
  '5. Una KEV nunca se minimiza por tener CVSS o EPSS bajo: la explotación ya está confirmada.',
  '6. EPSS es bajo en CVE recién publicados; no lo uses para descartar urgencia.',
  '7. Formato: texto plano para correo, con títulos cortos en MAYÚSCULAS y viñetas con "-". Sin markdown con asteriscos.',
  '8. Cierra con el enlace al tablero.',
].join('\n');

return Object.keys(ROLE).map(role => ({
  json: {
    role, to: RECIPIENTS[role],
    subject: `Pulso de vulnerabilidades · ${ROLE[role].nombre} · ${r.window.start} a ${r.window.end}`,
    request: {
      model: MODEL, max_tokens: 1500, system: SYSTEM,
      messages: [{ role: 'user', content:
        `Redacta el resumen semanal para: ${ROLE[role].nombre}.\nFoco: ${ROLE[role].foco}\nExtensión: ${ROLE[role].largo}.\n\nDATOS (JSON):\n${JSON.stringify(facts[role])}` }],
    },
  },
}));

// Une la respuesta de Claude con destinatario y asunto del ítem original.
const src = $('Preparar datos por rol').all();
return $input.all().map((it, i) => {
  const body = it.json.content && it.json.content[0] ? it.json.content[0].text
             : `No se pudo generar el resumen: ${JSON.stringify(it.json.error || it.json).slice(0, 300)}`;
  return { json: { to: src[i].json.to, subject: src[i].json.subject, text: body } };
});
